/* ============================================
   COMBOBOX COMPONENT
   Filterable text field + listbox, with optional
   multi-select chips and async loading state
   ============================================ */

.ds-combobox {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200); /* 8px */
  width: 100%;
  position: relative;
}

/* ============================================
   LABEL
   ============================================ */

/* ============================================
   CONTROL
   ============================================ */

.ds-combobox__control {
  display: flex;
  align-items: center;
  gap: var(--gap-200); /* 8px */
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  border: var(--border-025) solid var(--color-input-border-primary);
  border-radius: var(--radius-300); /* 12px */
  background-color: var(--color-input-bg-primary);
  cursor: text;
  transition: border-color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-combobox__control:hover {
  border-color: var(--color-input-border-hover);
}

.ds-combobox--open .ds-combobox__control,
.ds-combobox__control:focus-within {
  border-color: var(--color-input-border-selected);
}

.ds-combobox__search-icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-primary);
  flex-shrink: 0;
}

/* ============================================
   FIELD — chips + text input share one line
   ============================================ */

.ds-combobox__field {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--gap-100); /* 4px */
  flex: 1;
  min-width: 0;
}

.ds-combobox__input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background-color: transparent;
  padding: 0;
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-input-text-primary);
}

.ds-combobox__input::placeholder {
  color: var(--color-input-text-placeholder);
}

/* ============================================
   CHIPS — multi-select selections
   ============================================ */

.ds-combobox__chip {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-050); /* 2px */
  padding: var(--padding-050) var(--padding-200); /* 2px 8px */
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-primary);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-primary);
  max-width: 100%;
}

.ds-combobox__chip-remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill);
  background-color: transparent;
  color: var(--color-icon-primary);
  cursor: pointer;
  transition: color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-combobox__chip-remove:hover {
  color: var(--color-text-primary);
}

.ds-combobox__chip-remove:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 1px;
}

.ds-combobox__chip-remove .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

/* ============================================
   CLEAR + CHEVRON
   ============================================ */

.ds-combobox__clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill);
  background-color: transparent;
  color: var(--color-icon-primary);
  cursor: pointer;
  flex-shrink: 0;
  transition: color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-combobox__clear:hover {
  color: var(--color-text-primary);
}

.ds-combobox__clear:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-combobox__clear .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

.ds-combobox__chevron {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-primary);
  transition: transform var(--motion-duration-base) var(--motion-ease-standard);
  flex-shrink: 0;
}

.ds-combobox--open .ds-combobox__chevron {
  transform: rotate(180deg);
}

/* ============================================
   MENU
   Floating surface — the one place a shadow is
   allowed, via the shared elevation token
   ============================================ */

.ds-combobox__menu {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  margin-top: var(--gap-050); /* 2px */
  padding: var(--padding-100);
  border: var(--border-025) solid var(--color-input-border-primary);
  border-radius: var(--radius-300); /* 12px */
  background-color: var(--color-bg-page-primary);
  list-style: none;
  max-height: 280px;
  overflow-y: auto;
  z-index: 10;
  box-shadow: var(--shadow-floating);
  animation: ds-combobox-appear var(--motion-duration-fast) var(--motion-ease-entrance);
}

@keyframes ds-combobox-appear {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* ============================================
   OPTION
   ============================================ */

.ds-combobox__option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap-200);
  padding: var(--padding-200) var(--padding-300); /* 8px 12px */
  border-radius: var(--radius-200);
  cursor: pointer;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-combobox__option:hover,
.ds-combobox__option--focused {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-combobox__option--selected .ds-combobox__option-label {
  color: var(--color-action-primary-text-tertiary);
}

.ds-combobox__option--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-combobox__option--disabled:hover {
  background-color: transparent;
}

.ds-combobox__option-text {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
  min-width: 0;
}

.ds-combobox__option-label {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

.ds-combobox__option-description {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
}

.ds-combobox__check {
  --icon-size: var(--icon-size-600);
  color: var(--color-action-primary-bg);
  flex-shrink: 0;
}

/* ============================================
   GROUPS
   ============================================ */

.ds-combobox__group {
  list-style: none;
}

.ds-combobox__group-label {
  display: block;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  padding: var(--padding-150) var(--padding-300);
  user-select: none;
}

.ds-combobox__group-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

/* ============================================
   STATUS ROW — loading / empty
   ============================================ */

.ds-combobox__status {
  padding: var(--padding-200) var(--padding-300);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  list-style: none;
}

/* ============================================
   HELPER TEXT
   ============================================ */

/* ============================================
   ERROR STATE
   ============================================ */

.ds-combobox--error .ds-combobox__control {
  border-color: var(--color-status-error-border);
}

/* ============================================
   DISABLED STATE
   ============================================ */

.ds-combobox--disabled .ds-combobox__control {
  background-color: var(--color-input-bg-disabled);
  border-color: var(--color-input-border-disabled);
  cursor: not-allowed;
}

.ds-combobox--disabled .ds-combobox__input {
  color: var(--color-input-text-disabled);
  cursor: not-allowed;
}

.ds-combobox--disabled .ds-combobox__search-icon,
.ds-combobox--disabled .ds-combobox__chevron {
  color: var(--color-input-text-disabled);
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-combobox--compact .ds-combobox__control {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
}

.ds-combobox--compact .ds-combobox__input,
.ds-combobox--compact .ds-combobox__option-label {
  font-size: var(--font-paragraph-sm-emphasis-size);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

.ds-combobox--compact .ds-combobox__option {
  padding: var(--padding-150) var(--padding-200); /* 6px 8px */
}

.ds-combobox--compact .ds-combobox__search-icon,
.ds-combobox--compact .ds-combobox__chevron,
.ds-combobox--compact .ds-combobox__check {
  --icon-size: var(--icon-size-500);
}

/* ============================================
   REDUCED MOTION
   ============================================ */

@media (prefers-reduced-motion: reduce) {
  .ds-combobox__menu {
    animation: none;
  }
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-combobox .material-symbols-rounded {
  color: inherit;
}

'use client';

import React, { useState, useRef, useEffect, useCallback, useMemo, useId } from 'react';
import { Field } from '../Field/Field';
import './Combobox.css';
import '../../fonts/material-symbols.css';

export interface ComboboxOption {
  /** Display label — also the text matched when filtering */
  label: string;
  /** Option value */
  value: string;
  /** Optional secondary line shown under the label */
  description?: string;
  /** Whether this option is disabled */
  disabled?: boolean;
}

export interface ComboboxOptionGroup {
  /** Group heading */
  label: string;
  /** Options within the group */
  options: ComboboxOption[];
}

/** Props owned by Combobox itself — everything else falls through to the wrapper. */
type ComboboxOwnProps = {
  /** Combobox label text */
  label?: string;
  /** Placeholder shown in the text field when nothing is selected */
  placeholder?: string;
  /**
   * Selected value — a `string` in single mode, `string[]` when `multiple`
   * is set. Leave undefined for an empty selection.
   */
  value?: string | string[];
  /** Available options (flat list) */
  options: ComboboxOption[];
  /** Optional grouped options — when provided, `options` is ignored */
  groups?: ComboboxOptionGroup[];
  /** Allow selecting more than one option; selections render as removable chips */
  multiple?: boolean;
  /** Component size */
  size?: 'default' | 'compact';
  /** Whether the combobox is disabled */
  disabled?: boolean;
  /** Whether the combobox is required */
  required?: boolean;
  /** Error state — shows error styling and message */
  error?: boolean;
  /** Helper or error message displayed below the field */
  helperText?: string;
  /** Show a loading affordance in the menu — for async option fetching */
  loading?: boolean;
  /** Message shown when the filter matches no options */
  emptyMessage?: string;
  /** Show a clear button once something is selected */
  clearable?: boolean;
  /**
   * Called with the new selection — a `string` in single mode,
   * `string[]` when `multiple` is set.
   */
  onValueChange?: (value: string | string[]) => void;
  /** Called as the user types, for async/server-side filtering */
  onSearchChange?: (query: string) => void;
  /** Skip built-in filtering — use when options are filtered upstream */
  manualFiltering?: boolean;
  /** Additional CSS classes */
  className?: string;
  /**
   * Legacy change handler, kept for backwards compatibility.
   *
   * @deprecated Use `onValueChange` instead.
   */
  onChange?: (value: string | string[]) => void;
  /**
   * Legacy accessible-name prop.
   *
   * @deprecated Pass the native `aria-label` attribute instead.
   */
  ariaLabel?: string;
  /**
   * Used only as a fallback for deriving the element id (`id || name || generated`).
   *
   * Note: Combobox renders a `<div>` wrapper around a text input, not a native
   * `<select>`, so `name` does **not** make the selection participate in native
   * form submission.
   */
  name?: string;
};

export interface ComboboxProps
  extends ComboboxOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof ComboboxOwnProps> {}

/**
 * Combobox component — a text field combined with a filterable listbox.
 * Unlike Dropdown (a static select), it narrows options as the user types
 * and supports multi-select chips and async option loading.
 *
 * Forwards a ref to the wrapping element and spreads unrecognised props onto it.
 */
export const Combobox = React.forwardRef<HTMLDivElement, ComboboxProps>(({
  label,
  placeholder = 'Search…',
  value,
  options,
  groups,
  multiple = false,
  size = 'default',
  disabled = false,
  required = false,
  error = false,
  helperText,
  loading = false,
  emptyMessage = 'No results found',
  clearable = false,
  onValueChange,
  onChange,
  onSearchChange,
  manualFiltering = false,
  className = '',
  ariaLabel,
  name,
  id,
  ...rest
}, ref) => {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const generatedId = useId();

  /** Keep the internal ref (used for click-outside) while honouring a forwarded one. */
  const setRootRef = (node: HTMLDivElement | null) => {
    rootRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  };

  const baseClass = 'ds-combobox';
  const isGrouped = Boolean(groups && groups.length > 0);
  const inputId = id || name || generatedId;

  // Normalise the selection to an array regardless of mode
  const selectedValues = useMemo<string[]>(() => {
    if (value === undefined || value === null) return [];
    return Array.isArray(value) ? value : [value];
  }, [value]);

  const allOptions = useMemo<ComboboxOption[]>(
    () => (isGrouped ? groups!.flatMap((g) => g.options) : options),
    [isGrouped, groups, options]
  );

  const matches = useCallback(
    (option: ComboboxOption) => {
      if (manualFiltering || query.trim() === '') return true;
      return option.label.toLowerCase().includes(query.trim().toLowerCase());
    },
    [manualFiltering, query]
  );

  // Filtered view, preserving group structure for rendering
  const filteredGroups = useMemo<ComboboxOptionGroup[]>(() => {
    if (!isGrouped) return [];
    return groups!
      .map((group) => ({ ...group, options: group.options.filter(matches) }))
      .filter((group) => group.options.length > 0);
  }, [isGrouped, groups, matches]);

  const filteredOptions = useMemo<ComboboxOption[]>(
    () => (isGrouped ? filteredGroups.flatMap((g) => g.options) : options.filter(matches)),
    [isGrouped, filteredGroups, options, matches]
  );

  const selectedOptions = useMemo(
    () =>
      selectedValues
        .map((v) => allOptions.find((opt) => opt.value === v))
        .filter((opt): opt is ComboboxOption => Boolean(opt)),
    [selectedValues, allOptions]
  );

  const singleSelected = !multiple ? selectedOptions[0] : undefined;

  // In single mode the field shows the selected label until the user types
  const inputValue = isOpen || multiple ? query : singleSelected?.label ?? '';

  const openMenu = () => {
    if (disabled) return;
    setIsOpen(true);
    setFocusedIndex(-1);
  };

  const closeMenu = () => {
    setIsOpen(false);
    setFocusedIndex(-1);
    setQuery('');
  };

  const emitChange = (next: string[]) => {
    const payload = multiple ? next : (next[0] ?? '');
    onValueChange?.(payload);
    onChange?.(payload);
  };

  const handleSelect = (option: ComboboxOption) => {
    if (option.disabled) return;

    if (multiple) {
      const next = selectedValues.includes(option.value)
        ? selectedValues.filter((v) => v !== option.value)
        : [...selectedValues, option.value];
      emitChange(next);
      setQuery('');
      setFocusedIndex(-1);
      inputRef.current?.focus();
    } else {
      emitChange([option.value]);
      closeMenu();
      inputRef.current?.blur();
    }
  };

  const handleRemove = (optionValue: string) => {
    emitChange(selectedValues.filter((v) => v !== optionValue));
    inputRef.current?.focus();
  };

  const handleClear = () => {
    emitChange([]);
    setQuery('');
    inputRef.current?.focus();
  };

  const handleQueryChange = (next: string) => {
    setQuery(next);
    setFocusedIndex(-1);
    if (!isOpen) setIsOpen(true);
    onSearchChange?.(next);
  };

  const handleClickOutside = useCallback((e: MouseEvent) => {
    if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
      setIsOpen(false);
      setFocusedIndex(-1);
      setQuery('');
    }
  }, []);

  useEffect(() => {
    if (!isOpen) return;
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen, handleClickOutside]);

  const moveFocus = (direction: 1 | -1) => {
    setFocusedIndex((prev) => {
      let next = prev + direction;
      while (next >= 0 && next < filteredOptions.length && filteredOptions[next].disabled) {
        next += direction;
      }
      if (next < 0 || next >= filteredOptions.length) return prev;
      return next;
    });
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (disabled) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        if (!isOpen) {
          openMenu();
        } else {
          moveFocus(1);
        }
        break;
      case 'ArrowUp':
        e.preventDefault();
        if (isOpen) moveFocus(-1);
        break;
      case 'Enter':
        if (isOpen && focusedIndex >= 0 && filteredOptions[focusedIndex]) {
          e.preventDefault();
          handleSelect(filteredOptions[focusedIndex]);
        }
        break;
      case 'Escape':
        if (isOpen) {
          e.preventDefault();
          closeMenu();
        }
        break;
      case 'Backspace':
        // Empty query in multi mode — pop the last chip
        if (multiple && query === '' && selectedValues.length > 0) {
          emitChange(selectedValues.slice(0, -1));
        }
        break;
      case 'Tab':
        setIsOpen(false);
        setFocusedIndex(-1);
        setQuery('');
        break;
    }
  };

  // Keep the active option in view during keyboard navigation
  useEffect(() => {
    if (!isOpen || focusedIndex < 0 || !listRef.current) return;
    const active = listRef.current.querySelector<HTMLElement>(
      `[data-option-index="${focusedIndex}"]`
    );
    active?.scrollIntoView({ block: 'nearest' });
  }, [focusedIndex, isOpen]);

  const listboxId = `${inputId}-listbox`;
  const activeOptionId =
    focusedIndex >= 0 && filteredOptions[focusedIndex]
      ? `${inputId}-option-${filteredOptions[focusedIndex].value}`
      : undefined;

  const classes = [
    baseClass,
    size === 'compact' ? `${baseClass}--compact` : '',
    isOpen ? `${baseClass}--open` : '',
    error ? `${baseClass}--error` : '',
    disabled ? `${baseClass}--disabled` : '',
    multiple ? `${baseClass}--multiple` : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  const renderOption = (option: ComboboxOption, index: number) => {
    const isSelected = selectedValues.includes(option.value);
    return (
      <li
        key={option.value}
        id={`${inputId}-option-${option.value}`}
        data-option-index={index}
        className={[
          `${baseClass}__option`,
          isSelected ? `${baseClass}__option--selected` : '',
          option.disabled ? `${baseClass}__option--disabled` : '',
          index === focusedIndex ? `${baseClass}__option--focused` : '',
        ]
          .filter(Boolean)
          .join(' ')}
        role="option"
        aria-selected={isSelected}
        aria-disabled={option.disabled}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => handleSelect(option)}
      >
        <span className={`${baseClass}__option-text`}>
          <span className={`${baseClass}__option-label`}>{option.label}</span>
          {option.description && (
            <span className={`${baseClass}__option-description`}>{option.description}</span>
          )}
        </span>
        {isSelected && (
          <span className={`${baseClass}__check material-symbols-rounded`} aria-hidden="true">
            check
          </span>
        )}
      </li>
    );
  };

  const hasSelection = selectedValues.length > 0;

  return (
    <Field
      {...rest}
      className={classes}
      ref={setRootRef}
      label={label}
      helperText={helperText}
      error={error}
      required={required}
      disabled={disabled}
      size={size}
      id={inputId}
    >
      <div className={`${baseClass}__control`} onClick={() => inputRef.current?.focus()}>
        <span className={`${baseClass}__search-icon material-symbols-rounded`} aria-hidden="true">
          search
        </span>

        <div className={`${baseClass}__field`}>
          {multiple &&
            selectedOptions.map((option) => (
              <span key={option.value} className={`${baseClass}__chip`}>
                {option.label}
                <button
                  type="button"
                  className={`${baseClass}__chip-remove`}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleRemove(option.value);
                  }}
                  disabled={disabled}
                  aria-label={`Remove ${option.label}`}
                >
                  <span className="material-symbols-rounded" aria-hidden="true">
                    close
                  </span>
                </button>
              </span>
            ))}

          <input
            ref={inputRef}
            id={inputId}
            name={name}
            type="text"
            className={`${baseClass}__input`}
            role="combobox"
            autoComplete="off"
            aria-expanded={isOpen}
            aria-controls={listboxId}
            aria-autocomplete="list"
            aria-activedescendant={activeOptionId}
            aria-label={ariaLabel || rest['aria-label'] || (!label ? placeholder : undefined)}
            aria-describedby={helperText ? `${inputId}-helper` : undefined}
            aria-invalid={error || undefined}
            aria-required={required || undefined}
            placeholder={multiple && hasSelection ? '' : placeholder}
            value={inputValue}
            disabled={disabled}
            onChange={(e) => handleQueryChange(e.target.value)}
            onFocus={openMenu}
            onKeyDown={handleKeyDown}
          />
        </div>

        {clearable && hasSelection && !disabled && (
          <button
            type="button"
            className={`${baseClass}__clear`}
            onClick={(e) => {
              e.stopPropagation();
              handleClear();
            }}
            aria-label="Clear selection"
          >
            <span className="material-symbols-rounded" aria-hidden="true">
              close
            </span>
          </button>
        )}

        <span className={`${baseClass}__chevron material-symbols-rounded`} aria-hidden="true">
          expand_more
        </span>
      </div>

      {isOpen && (
        <ul className={`${baseClass}__menu`} role="listbox" id={listboxId} ref={listRef}>
          {loading && (
            <li className={`${baseClass}__status`} role="presentation">
              Loading…
            </li>
          )}

          {!loading && filteredOptions.length === 0 && (
            <li className={`${baseClass}__status`} role="presentation">
              {emptyMessage}
            </li>
          )}

          {!loading &&
            (isGrouped
              ? (() => {
                  let flatIndex = 0;
                  return filteredGroups.map((group) => (
                    <li key={group.label} className={`${baseClass}__group`} role="none">
                      <span className={`${baseClass}__group-label`} role="presentation">
                        {group.label}
                      </span>
                      <ul
                        className={`${baseClass}__group-list`}
                        role="group"
                        aria-label={group.label}
                      >
                        {group.options.map((option) => renderOption(option, flatIndex++))}
                      </ul>
                    </li>
                  ));
                })()
              : filteredOptions.map((option, index) => renderOption(option, index)))}
        </ul>
      )}

    </Field>
  );
});

Combobox.displayName = 'Combobox';
